using System;using System.Linq;using System.Collections.Generic;using System.Drawing;
public class UsageStop {public double Position;public string Color;}
public class UsageRamp {
 public bool Enabled=true,FollowValue;public string Mode="smooth";public int Cells=18;public List<UsageStop> Stops=new List<UsageStop>();
 public static readonly string[] Presets={"侦探蓝","薄荷警戒","NVIDIA 绿","英特尔蓝","Radeon 赤","网络极光","基德月光","霞光琥珀","额度余量"};
 public static UsageRamp Preset(string name){string[] colors;switch(name){case "薄荷警戒":colors=new[]{"#10B981","#84CC16","#FACC15","#F97316"};break;case "NVIDIA 绿":colors=new[]{"#155E27","#76B900","#C9E54D","#FF9F35"};break;case "英特尔蓝":colors=new[]{"#003C71","#0068B5","#00AEEF","#99E5FF"};break;case "Radeon 赤":colors=new[]{"#B94B79","#ED1C24","#F97316","#FBBF24"};break;case "网络极光":colors=new[]{"#2563EB","#06B6D4","#2DD4BF","#FDBA74"};break;case "基德月光":colors=new[]{"#7EA3CC","#C2CBE5","#B4A2E8","#E8BA72"};break;case "霞光琥珀":colors=new[]{"#FDA4AF","#F9BF70","#F97316","#DC425A"};break;case "额度余量":colors=new[]{"#EF4444","#F59E0B","#34D399","#60A5FA"};break;default:colors=new[]{"#3B82F6","#22D3EE","#EACC52","#F78742"};break;}return new UsageRamp{Stops=colors.Select((c,i)=>new UsageStop{Position=new[]{0d,50,80,100}[i],Color=c}).ToList()};}
 public static UsageRamp Between(string first,string last,bool enabled=true){return new UsageRamp{Enabled=enabled,Stops=new List<UsageStop>{new UsageStop{Position=0,Color=first},new UsageStop{Position=100,Color=last}}};}
 public Color Sample(double percent){return At(Mode=="mosaic"?Math.Min(100,(Math.Floor(Math.Max(0,Math.Min(99.999,percent))/100*Cells)+.5)/Cells*100):percent);}
 public UsageRamp ForValue(double percent){
  if(!FollowValue||Double.IsNaN(percent)||Double.IsInfinity(percent))return this;
  percent=Math.Max(0,Math.Min(100,percent));double start=percent-15,end=percent+15;
  var positions=new[]{0d,100d}.Concat(Stops.Where(s=>s.Position>start&&s.Position<end).Select(s=>(s.Position-start)/30*100)).Distinct().OrderBy(p=>p);
  return new UsageRamp{Enabled=Enabled,Mode=Mode,Cells=Cells,Stops=positions.Select(p=>{var c=At(start+p*.3);return new UsageStop{Position=p,Color="#"+c.R.ToString("X2")+c.G.ToString("X2")+c.B.ToString("X2")};}).ToList()};
 }
 public bool MoveStop(int index,double position){if(index<0||index>=Stops.Count||Double.IsNaN(position)||Double.IsInfinity(position))return false;var point=Stops[index];if(point.Position==0||point.Position==100)return false;double min=Stops.Where(p=>p.Position<point.Position).Max(p=>p.Position),max=Stops.Where(p=>p.Position>point.Position).Min(p=>p.Position);double next=Math.Round(Math.Max(min+.1,Math.Min(max-.1,position)),1);if(next<=min||next>=max||next==point.Position)return false;point.Position=next;return true;}
 public UsageRamp Copy(){return new UsageRamp{Enabled=Enabled,FollowValue=FollowValue,Mode=Mode,Cells=Cells,Stops=Stops.Select(s=>new UsageStop{Position=s.Position,Color=s.Color}).ToList()};}
 public void Validate(){if(Mode!="smooth"&&Mode!="mosaic"||Cells<3||Cells>60||Stops==null||Stops.Count<2||Stops.Count>16||Stops.Any(s=>s==null||Double.IsNaN(s.Position)||Double.IsInfinity(s.Position)||s.Position<0||s.Position>100)||Stops.Select(s=>s.Position).Distinct().Count()!=Stops.Count||!Stops.Any(s=>s.Position==0)||!Stops.Any(s=>s.Position==100))throw new ArgumentException("配色条需2–16个不同位置的颜色点，保留0%和100%，色块数量3–60。");foreach(var s in Stops)TaskbarAppearance.ParseColor(s.Color);}
 public Color At(double percent){var ordered=Stops.OrderBy(s=>s.Position).ToArray();percent=Math.Max(0,Math.Min(100,percent));var a=ordered.LastOrDefault(s=>s.Position<=percent)??ordered[0];var b=ordered.FirstOrDefault(s=>s.Position>=percent)??ordered[ordered.Length-1];var first=TaskbarAppearance.ParseColor(a.Color);var last=TaskbarAppearance.ParseColor(b.Color);double f=b.Position<=a.Position?0:(percent-a.Position)/(b.Position-a.Position);return Color.FromArgb((int)Math.Round(first.R+(last.R-first.R)*f),(int)Math.Round(first.G+(last.G-first.G)*f),(int)Math.Round(first.B+(last.B-first.B)*f));}
 public void Draw(Graphics g,RectangleF area,double fraction){float width=(float)(area.Width*Math.Max(0,Math.Min(1,fraction)));if(area.Width<=0||area.Height<=0||width<=0)return;if(FollowValue){ForValue(fraction*100).Draw(g,new RectangleF(area.X,area.Y,width,area.Height),1);return;}if(Mode=="smooth"){var ordered=Stops.OrderBy(s=>s.Position).ToArray();using(var brush=new System.Drawing.Drawing2D.LinearGradientBrush(area,At(0),At(100),0f)){brush.InterpolationColors=new System.Drawing.Drawing2D.ColorBlend{Colors=ordered.Select(s=>TaskbarAppearance.ParseColor(s.Color)).ToArray(),Positions=ordered.Select(s=>(float)(s.Position/100)).ToArray()};g.FillRectangle(brush,new RectangleF(area.X,area.Y,width,area.Height));}return;}float edge=area.X+width;for(int i=0;i<Cells;i++){float left=area.X+area.Width*i/Cells;if(left>=edge)break;float right=Math.Min(edge,area.X+area.Width*(i+1)/Cells);float gap=Math.Min(1,area.Width/Cells*.16f);using(var brush=new SolidBrush(At(100.0*(i+.5)/Cells)))g.FillRectangle(brush,left,area.Y,Math.Max(0,right-left-gap),area.Height);}}
}
